import{_ as l,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"23 | 模型核心技术指标：如何提高上下文长度？","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么超长上下文很重要？","slug":"为什么超长上下文很重要","link":"#为什么超长上下文很重要","children":[]},{"level":2,"title":"为什么会有上下文限制？","slug":"为什么会有上下文限制","link":"#为什么会有上下文限制","children":[{"level":3,"title":"计算资源限制","slug":"计算资源限制","link":"#计算资源限制","children":[]},{"level":3,"title":"内存消耗","slug":"内存消耗","link":"#内存消耗","children":[]},{"level":3,"title":"宽带限制","slug":"宽带限制","link":"#宽带限制","children":[]}]},{"level":2,"title":"如何支持更长上下文？","slug":"如何支持更长上下文","link":"#如何支持更长上下文","children":[{"level":3,"title":"稀疏注意力机制","slug":"稀疏注意力机制","link":"#稀疏注意力机制","children":[]},{"level":3,"title":"滑动窗口","slug":"滑动窗口","link":"#滑动窗口","children":[]},{"level":3,"title":"降采样","slug":"降采样","link":"#降采样","children":[]},{"level":3,"title":"模型训练方面","slug":"模型训练方面","link":"#模型训练方面","children":[]},{"level":3,"title":"模型推理方面","slug":"模型推理方面","link":"#模型推理方面","children":[]}]},{"level":2,"title":"大海捞针","slug":"大海捞针","link":"#大海捞针","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型实战高手课/23｜模型核心技术指标：如何提高上下文长度？.md","filePath":"AI大模型实战高手课/23｜模型核心技术指标：如何提高上下文长度？.md","lastUpdated":1795452664000}'),r={name:"AI大模型实战高手课/23｜模型核心技术指标：如何提高上下文长度？.md"};function o(n,e,p,h,s,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_23-模型核心技术指标-如何提高上下文长度" tabindex="-1">23 | 模型核心技术指标：如何提高上下文长度？ <a class="header-anchor" href="#_23-模型核心技术指标-如何提高上下文长度" aria-label="Permalink to &quot;23 | 模型核心技术指标：如何提高上下文长度？&quot;">​</a></h1><p>你好，我是独行。</p><p>这节课我会给你介绍大模型中非常重要的一个技术指标：上下文长度。我们知道，AI 问答类产品和传统问答类产品，在使用层面上有一个很重要的区别就是上下文，AI 问答产品可以根据上下文进行更加深层次的问答，给我们的感觉就是很智能，很人性化。</p><p>前阵子非常火的 AI 问答产品 Kimi，就是以超长上下文著称，比如支持 200 万字长文本输入，一次性输入几本书，可以准确进行内容整理输出；再比如 GPT-4-turbo，支持 128K 上下文长度，还有像 6B，最新版本已经支持 32K 上下文长度。</p><p>以前各大厂商在宣传自己的产品的时候，讲的最主要的一方面就是参数规模，现在除了参数规模，还经常提的就是支持的上下文长度，所以业界有人笑称，大模型卷完参数，开始卷上下文了。今年 3 月份，阿里云通义千问已经将上下文长度直接提升至 1000 万字，是 Kimi 的 5倍，而且免费提供给客户使用，一下子卷到了极致。</p><p>那么为什么大厂都开始卷上下文长度了呢？</p><h2 id="为什么超长上下文很重要" tabindex="-1">为什么超长上下文很重要？ <a class="header-anchor" href="#为什么超长上下文很重要" aria-label="Permalink to &quot;为什么超长上下文很重要？&quot;">​</a></h2><p>用 Kimi 所在公司月之暗面（Moonshot）的创始人杨植麟的话说，Lossless long context iseverything，杨植麟判断 AI 产品的终极价值是提供个性化的交互，而lossless long-context 是实现这一点的基础。模型的微调不应该⻓期存在， 用户跟模型的交互历史就是最好的个性化过程。</p><p>我们知道，在传统计算中有两个核心原则：计算是按照顺序逐步进行的，每一步都有有限的复杂度容量。大型语言模型可以被看作是进化了的计算实体，所以大模型能够达到的最高水平由两个因素决定：一个是单步骤的容量，即模型在每一步中可以处理的信息量，对应参数量；另一个是执行的步骤数，也就是模型能够处理的上下文⻓度。</p><p>目前，大部分大模型研究都集中在增加模型参数量的大小，即增强「单步骤容量」。但是在保持一定参数量的同时放大另一个维度，即「步骤数」或上下文⻓度也同样重要。上下文窗口就像大模型应用的新「内存」，窗口越大，用户能用它做的事情就越广泛；同时，窗口所能容纳的信息越多，模型在生成下一个 token 时可以参考的信息就越多，「幻觉」发生的可能性就越小，生成的信息就越准确。</p><p>举几个很实际的例子。</p><ol><li><p>招聘场景，在系统上传 50 份简历，每份简历都是一个 PDF文档，50 个简历上传之后，提要求，比如要具备一定的英语水平，有比较强的技术背景等，智能助手在阅读完这 50 份简历之后，⻢上就给出来了 Top5 推荐，最后 Top2 的两个人刚好就是最后实际被录用的。</p></li><li><p>再比如打⻋发票整理，直接上传 50 个发票，智能助手可以自动整理你过去一个月的行程到底是什么样的，直接整理出来一个报销文档。</p></li><li><p>又或者有好几篇英文论文，你想做比较、分析，智能助手可以利用它的⻓文本能力，很好地完成任务。</p></li></ol><h2 id="为什么会有上下文限制" tabindex="-1">为什么会有上下文限制？ <a class="header-anchor" href="#为什么会有上下文限制" aria-label="Permalink to &quot;为什么会有上下文限制？&quot;">​</a></h2><h3 id="计算资源限制" tabindex="-1">计算资源限制 <a class="header-anchor" href="#计算资源限制" aria-label="Permalink to &quot;计算资源限制&quot;">​</a></h3><p>就拿 Transformer 架构来讲，前面我们讲过注意力机制，所有的输入会被切分成一个一个token，注意力机制就是在预测下一个词的时候，可以计算当前 token 和其他 token 的关系，如果输入序列非常大，切分出来的 token 就多，注意力机制计算的时候，需要的算力就会更大。</p><p>Transformer 模型中自注意力机制的计算量。会随着上下文⻓度的增加呈平方级增⻓，比如上下文长度增加 32 倍时，计算量实际会增⻓1000 倍，这意味着如果只是用朴素的方式实现，用户需要等待极其⻓的时间才能获得反馈，所以如果想要获得快速反馈，那么必须增加算力，这是核心原因。</p><h3 id="内存消耗" tabindex="-1">内存消耗 <a class="header-anchor" href="#内存消耗" aria-label="Permalink to &quot;内存消耗&quot;">​</a></h3><p>随着输入序列长度的增加，模型在每个处理步骤中需要保留更多的中间状态信息。这会显著增加 GPU 或其他处理器的内存需求。在实践中，这个问题限制了模型能够处理的最大序列长度，以适应可用的硬件资源。</p><h3 id="宽带限制" tabindex="-1">宽带限制 <a class="header-anchor" href="#宽带限制" aria-label="Permalink to &quot;宽带限制&quot;">​</a></h3><p>以 1750 亿参数的 GPT-3 为例，目前最高单机配置（80GiB * 8）最多只能支持 64k 上下文⻓度的推理，超⻓文本对显存的要求可⻅一斑。这带来了极大的显存带宽压力：英伟达 A800 或H800 的显存带宽高达 2～3TB/s，但面对如此⻓的上下文，一般方法的生成速度只能达到 2～5tokens/s，使用的时候极其卡顿，体验很糟。</p><h2 id="如何支持更长上下文" tabindex="-1">如何支持更长上下文？ <a class="header-anchor" href="#如何支持更长上下文" aria-label="Permalink to &quot;如何支持更长上下文？&quot;">​</a></h2><p>关于支持更长上下文，我们来看目前业界常用的一些方法。</p><h3 id="稀疏注意力机制" tabindex="-1">稀疏注意力机制 <a class="header-anchor" href="#稀疏注意力机制" aria-label="Permalink to &quot;稀疏注意力机制&quot;">​</a></h3><p>稀疏注意力机制是一种优化过的注意力计算方法，使用全连接注意力时，每个元素都会与序列中的其他元素计算注意力关系，而在稀疏注意力机制中，元素只与序列中选择的部分元素建立这种关系。这种选择可以基于预定义的模式，比如局部窗口、固定模式等，也可以是通过学习得到的动态模式。</p><p>稀疏注意力机制的主要优势是显著降低了计算复杂度和内存需求，使模型能够高效地处理更长的序列。这一机制特别适合需要模型理解和处理大范围上下文信息的应用。</p><h3 id="滑动窗口" tabindex="-1">滑动窗口 <a class="header-anchor" href="#滑动窗口" aria-label="Permalink to &quot;滑动窗口&quot;">​</a></h3><p>滑动窗口是一种简单的限制方法，用于减少自注意力计算的复杂度。在这种方法中，每个令牌只关注它附近的一小部分令牌。例如，如果设置窗口大小为 5，那么每个令牌只会与它前后两个位置的令牌进行交互（总共 5 个令牌）。这种方法能有效降低计算量，因为它限制了每次计算涉及的令牌数量。</p><p>滑动窗口和稀疏注意力都是减少注意力计算的方法，不过二者有区别。</p><ol><li><p>计算复杂度：滑动窗口通过简单地降低每个令牌关注的范围来减少复杂度，而稀疏注意力通过更智能的选择关注点来优化计算。</p></li><li><p>灵活性：滑动窗口技术相对固定，每个令牌的关注范围是固定的。稀疏注意力则更灵活，可以根据任务的需要调整关注的范围和模式。</p></li><li><p>实现难度：滑动窗口技术实现起来相对简单，而稀疏注意力可能需要复杂的数据结构和算法，尤其是在动态选择关注点的时候。</p></li></ol><h3 id="降采样" tabindex="-1">降采样 <a class="header-anchor" href="#降采样" aria-label="Permalink to &quot;降采样&quot;">​</a></h3><p>降采样就比较粗暴了，就是一种数据减少技术，减少输入序列，同时尽量保留重要信息，比如只选择序列中的某些部分单词，或通过合并相邻的元素，来创建一个更短的序列。比如当我们输入一本 20 万字的 PDF 书籍时，通过一定的策略，只取其中我们认为重要的内容，经过处理后，喂给模型的可能只有 2 万字。这样的方法优势劣势都很明显，优势就是可以让模型支持更长的上下文，劣势就是有可能丢失有用的信息，使模型的性能下降。</p><p>以上这些方式是比较常见的，不过也有人认为，这些都是解决上下文长度问题的“技术捷径”，牺牲的是模型的性能，因为无论是稀疏注意力、滑动窗口还是降采样，都是主动丢弃不重要的数据，那么在评估不重要的数据过程中，很有可能产生误判，从而影响模型性能。</p><p>那究竟什么方法不是捷径呢？在月之暗面披露的关于 Kimi 如何解决上下文长度问题的技术细节中，提到了这样的方式，我们一起来看下。</p><h3 id="模型训练方面" tabindex="-1">模型训练方面 <a class="header-anchor" href="#模型训练方面" aria-label="Permalink to &quot;模型训练方面&quot;">​</a></h3><p>在传统的 Tensor 并行、Data 并行、Pipeline 并行基础上，增加了多项基于 Seqence 维度的并行策略，提升了并行效率。利用定制版的 Flash Attention、Fuse Cross Entropy、CPUoffload 等技术大幅度降低了显存压力。还使用了创新的训练方法，针对性地调配了多阶段式训练方法，让模型保留基础能力的前提下，逐步激活⻓上下文的能力。</p><h3 id="模型推理方面" tabindex="-1">模型推理方面 <a class="header-anchor" href="#模型推理方面" aria-label="Permalink to &quot;模型推理方面&quot;">​</a></h3><ul><li><p>用GQA 替换 MHA：让 KVCache 所占用的显存大小大幅度缩小。</p></li><li><p>2Paged attention：保证显存的充分利用。</p></li><li><p>低比特量化：通过 W8A8，最多可以把推理速度在上述基础上再提升一倍。</p></li><li><p>MoE &amp; KVCache 裁减：让显存占用在上述基础上再下降一倍。</p></li></ul><p>这些策略看着易懂，但是实际操作过程中也会有不少问题，甚至需要一边实践一边探索。如果你对哪一条感兴趣可以在评论区留言，我们一起讨论一下。</p><p>最后，给你看一个关于超长上下文测试的很有趣的例子——大海捞针。</p><h2 id="大海捞针" tabindex="-1">大海捞针 <a class="header-anchor" href="#大海捞针" aria-label="Permalink to &quot;大海捞针&quot;">​</a></h2><p>在文本语料中藏入一个与文本语料不相关的句子，比如在整本《西游记》里放入一句只会在《红楼梦》里出现的话，然后看大模型能不能通过自然语言提问的方式，即 Prompt，把这句话准确地提取出来。藏起来的那句话就是“针”，《西游记》就是大海。</p><p>国外有一个大模型开发者 Greg Kamradt，在 GPT-4 Trubo（128K）以及 Claude2.1（200K）上进行过测试，效果并不好，Kimi 的工程师用了相同的方法测试，经过几轮的测试，发现效果时好时坏，且有一些规律：效果好坏取决于 Prompt 和内容（即“大海”和“针”），而且并没有强一致的结果。</p><p>经过几轮测试，Kimi 的工程师发现，除了大模型本身的⻓文本记忆能力和指令遵循能力，其实还有两个关键点对结果起了明显作用： 一是藏在“大海”中的“针”是否完全没有歧义；二是向大模型提问的 Prompt 写得是否足够明确。</p><p>我觉得这块内容还有待进一步验证，其实大模型本身就面临可解释性的问题，更别提超长上下文了，更是迷上加迷，这就和我们人类到目前为止还没有搞清楚大脑的工作原理一样。有时又觉得其实也没那么重要，只要输出是正确的就行，只要输出正确，那我们就会信任大模型，至于原理究竟是什么，现阶段还不是最重要的课题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天这节课很有意思，也是大模型核心技术之一，目前看这块还是非常前沿的一个话题，因为已经很久没有人提过模型的参数了，ChatGPT、文心一言包括 Kimi 等等，已经很少提参数的事儿了，现在经常提的就是上下文长度和多模态，所以这块很有可能是大模型下一个技术突破点。</p><p>当然如果你说通义千问已经支持 1000 万字的上下文了，我觉得还得加个问号，到底效果怎么样，是不是通过捷径支持的，都还需要用户验证。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>超长上下文会带来注意力机制计算量的增加，你可以思考一下，怎么才能算出计算量增加多少？欢迎你把思路打在评论区，我们一起探讨，如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>',49)])])}const _=l(r,[["render",o]]);export{u as __pageData,_ as default};
